#include <planning/change_planner.hpp>
namespace rebuntu::planning { ChangePlan ChangePlanner::plan(const DesiredChange&d)const{ChangePlan p;p.id=d.domain+":"+d.target+":"+d.property;p.domain=d.domain;p.action="set";p.target=d.target;p.desired[d.property]=d.value;p.privileged=d.privileged;p.risk=d.destructive?platform::v0040::Risk::destructive:(d.privileged?platform::v0040::Risk::medium:platform::v0040::Risk::low);p.reversible=true;p.preconditions={"target exists","current state observed"};p.steps={"snapshot current state","apply desired "+d.property,"refresh observation"};p.verification={"observed "+d.property+" equals desired value"};p.rollback={"restore snapshot"};return p;} std::vector<std::string> ChangePlanner::validate(const ChangePlan&p)const{std::vector<std::string>e;if(p.domain.empty())e.push_back("domain missing");if(p.target.empty())e.push_back("target missing");if(p.desired.empty())e.push_back("desired state missing");if(p.verification.empty())e.push_back("verification missing");if(p.reversible&&p.rollback.empty())e.push_back("rollback missing");return e;} }
